INSERT INTO `v1_b075dd1e0090b3e307364ce4bf3210ef9ae7948b43081d7a8200160d46ecb597` VALUES (0, 321, 2, "リリ", 24001, 40011, 125801, 1, 1, 1, "もうすぐ、みなさまに\nお会いできるのですね。\n胸が高鳴ってしまいます……\n");
INSERT INTO `v1_b075dd1e0090b3e307364ce4bf3210ef9ae7948b43081d7a8200160d46ecb597` VALUES (0, 322, 2, "クリア", 24001, 40011, 126001, 2, 1, 1, "初めまして、クリアです♪\nみなさんと一緒に冒険するの\nとっても楽しみにしてます");
INSERT INTO `v1_b075dd1e0090b3e307364ce4bf3210ef9ae7948b43081d7a8200160d46ecb597` VALUES (0, 323, 2, "プレシア", 24001, 40011, 126101, 3, 1, 1, "んーと。\nこれ、あげる。\nはい");
INSERT INTO `v1_b075dd1e0090b3e307364ce4bf3210ef9ae7948b43081d7a8200160d46ecb597` VALUES (0, 324, 2, "リリ", 24001, 40011, 125801, 4, 2, 1, "あらためまして……\n【アルターメイデン】の\nギルドマスター、リリと申します");
INSERT INTO `v1_b075dd1e0090b3e307364ce4bf3210ef9ae7948b43081d7a8200160d46ecb597` VALUES (0, 325, 2, "クリア", 24001, 40011, 126001, 5, 2, 1, "こんにちは、お兄さん♪\n【アルターメイデン】の\nクリアです");
INSERT INTO `v1_b075dd1e0090b3e307364ce4bf3210ef9ae7948b43081d7a8200160d46ecb597` VALUES (0, 326, 2, "プレシア", 24001, 40011, 126101, 6, 2, 1, "お兄。\nきてくれて、うれしい");
